KG42.register("rules-6a1446139d002583530e8cc5",{"id":"44-blockchain_phev_trading::v141-c-R002","paper":"44-blockchain_phev_trading","record":{"rule_id":"v141-c-R002","mechanism_id":"v141-a-M01","name":"Local market clearing","process_stage":"clearing","market_meaning":"The local energy broker acting as auctioneer solves Problem A to determine the quantities of electricity allocated locally. Scope: Problem A in the iterative double auction within one hotspot served by an LAG. Problem A maximizes buyer-bid-weighted logarithmic demand minus seller-bid-weighted supply. Allocations must satisfy charging-efficiency-adjusted minimum and maximum demand bounds, maximum total supply for each seller, transmission-adjusted bilateral supply-demand equality and nonnegative demand quantities. Scope: Local demand and supply allocations determined by Problem A within one LAG. The bid-convergence stopping rule terminates the iterative local allocation procedure when both relative bid-price differences fall below ε. Scope: Convergence testing in the unchanged-participant branch of Algorithm 1 for local allocation. Condition: The newest bid prices satisfy both RDB\u003cε and RDS\u003cε. The local allocation and bid-update steps repeat while the bid-price convergence test is not satisfied. Scope: Convergence testing in the unchanged-participant branch of Algorithm 1 for local allocation. Condition: The newest bid prices do not satisfy both RDB\u003cε and RDS\u003cε. The current local allocation procedure is terminated and a restart of Algorithm 1 is prepared. Scope: Participant-change branch of Algorithm 1 during current localized P2P trading. Condition: The participating PHEVs of the current localized P2P electricity trading change. Algorithm 1 may be restarted with its parameters reinitialized on demand. Scope: On-demand restart of the localized iterative allocation procedure following an unexpected event. Condition: An unexpected event, such as abrupt disconnection of scheduled PHEVs, activates a trigger.","independence_rationale":"Relations governed by the approved function clearing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","coordination.local_operator"],"E":[{"edge_id":"v141-c-R002-E001","source":"coordination.local_operator","target":"clearing.local","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g02-E08","v141-b-g02-E11"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Convergence testing in the unchanged-participant branch of Algorithm 1 for local allocation. | Local demand and supply allocations determined by Problem A within one LAG. | On-demand restart of the localized iterative allocation procedure following an unexpected event. | Participant-change branch of Algorithm 1 during current localized P2P trading. | Problem A in the iterative double auction within one hotspot served by an LAG.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E04","v141-b-g02-E08","v141-b-g02-E11","v141-b-g02-E18","v141-b-g02-E19","v141-b-g02-E20"]},"x":[{"variable_id":"v141-c-R002-x-Cn","symbol":"C^n","meaning":"Total electricity demand allocation of all charging PHEVs in LAG n, represented as C^n={C_i^n | i∈C} with C_i^n={c_{ij}^n | j∈Z}.","kind":"operational","domain":"collection of electricity demand allocations c_{ij}^n indexed by i∈C and j∈Z","unit":"kWh","indices":["n"],"evidence_ids":["v141-b-g02-E00","v141-b-g02-E04","v141-b-g02-E11","v141-b-g02-E23"]},{"variable_id":"v141-c-R002-x-Dn","symbol":"D^n","meaning":"Total electricity supply allocation of all discharging PHEVs in LAG n, represented as D^n={D_j^n | j∈Z}, with components d_{ji}^n giving supply from DV_j^n to CV_i^n. The source prints i∈R in the D_j^n definition; R is not defined in the supplied text.","kind":"operational","domain":"collection of electricity supply allocations d_{ji}^n indexed by j∈Z and i∈C, with source-printed i∈R left unresolved","unit":"kWh","indices":["n"],"evidence_ids":["v141-b-g02-E02","v141-b-g02-E04","v141-b-g02-E11","v141-b-g02-E23"]},{"variable_id":"v141-c-R002-x-cij","symbol":"c_{ij}^n","meaning":"Electricity demand of charging PHEV CV_i^n assigned to discharging PHEV DV_j^n in LAG n.","kind":"operational","domain":"nonnegative real, as constrained by c_{ij}^n ≥ 0 in (4)","unit":"kWh","indices":["n","i","j"],"evidence_ids":["v141-b-g02-E00","v141-b-g02-E04","v141-b-g02-E11","v141-b-g02-E23"]},{"variable_id":"v141-c-R002-x-dji","symbol":"d_{ji}^n","meaning":"Amount of electricity supply from discharging PHEV DV_j^n to charging PHEV CV_i^n in LAG n.","kind":"operational","domain":"real-valued amount of electricity supply; source states an upper bound and the equality ρ d_{ji}^n = c_{ij}^n, but gives no explicit standalone lower bound","unit":"kWh","indices":["n","j","i"],"evidence_ids":["v141-b-g02-E02","v141-b-g02-E04","v141-b-g02-E11","v141-b-g02-E23"]}],"theta":[{"parameter_id":"v141-c-R002-p-b","symbol":"b_{ij}^n","meaning":"Buying bid price submitted by charging PHEV CV_i^n for discharging PHEV DV_j^n; the source states b_{ij} ≥ 0. It is a given input to Problem A within an iteration.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n","i","j"],"evidence_ids":["v141-b-g02-E08","v141-b-g02-E11"]},{"parameter_id":"v141-c-R002-p-s","symbol":"s_{ji}^n","meaning":"Selling bid price submitted by discharging PHEV DV_j^n for charging PHEV CV_i^n; the source states s_{ji} ≥ 0. It is a given input to Problem A within an iteration.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n","j","i"],"evidence_ids":["v141-b-g02-E08","v141-b-g02-E11"]},{"parameter_id":"v141-c-R002-p-eta","symbol":"η","meaning":"Average charging efficiency from discharging PHEVs to charging PHEV CV_i^n.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E01","v141-b-g02-E04"]},{"parameter_id":"v141-c-R002-p-rho","symbol":"ρ","meaning":"Average electricity transmission efficiency of the local electricity trading.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E04"]},{"parameter_id":"v141-c-R002-p-cmin","symbol":"c_i^{n,min}","meaning":"Minimum electricity demand for charging PHEV CV_i^n; LAG_n must provide this energy for normal driving.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["i","n"],"evidence_ids":["v141-b-g02-E00","v141-b-g02-E04","v141-b-g02-E23"]},{"parameter_id":"v141-c-R002-p-cmax","symbol":"c_i^{n,max}","meaning":"Maximum electricity demand for charging PHEV CV_i^n.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["i","n"],"evidence_ids":["v141-b-g02-E00","v141-b-g02-E04","v141-b-g02-E23"]},{"parameter_id":"v141-c-R002-p-Dmax","symbol":"D_j^{n,max}","meaning":"Maximum electricity supply for discharging PHEV DV_j^n.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["j","n"],"evidence_ids":["v141-b-g02-E02","v141-b-g02-E04","v141-b-g02-E23"]},{"parameter_id":"v141-c-R002-p-epsilon","symbol":"ε","meaning":"Convergence threshold for the relative bid-price differences RDB and RDS. It is an input to Algorithm 1; the numerical study sets ε=0.001.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E18","v141-b-g02-E19","v141-b-g02-E23"]}],"phi":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The local energy broker acting as auctioneer solves Problem A to determine the quantities of electricity allocated locally. Scope: Problem A in the iterative double auction within one hotspot served by an LAG.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E08","v141-b-g02-E11"]},{"constraint_id":"v141-c-R002-C002","kind":"mathematical","role":"core","statement":"Problem A maximizes buyer-bid-weighted logarithmic demand minus seller-bid-weighted supply. Allocations must satisfy charging-efficiency-adjusted minimum and maximum demand bounds, maximum total supply for each seller, transmission-adjusted bilateral supply-demand equality and nonnegative demand quantities. Scope: Local demand and supply allocations determined by Problem A within one LAG.","expression":"max_{C^n,D^n} ∑_{i=1}^{I}∑_{j=1}^{J} [ b_{ij}^n ln c_{ij}^n − s_{ji}^n d_{ji}^n ] subject to c_i^{n,min} ≤ η ∑_{j=1}^{J} c_{ij}^n ≤ c_i^{n,max}, ∀i∈C; ∑_{i=1}^{I} d_{ji}^n ≤ D_j^{n,max}, ∀j∈Z; ρ d_{ji}^n = c_{ij}^n, ∀i∈C, ∀j∈Z; c_{ij}^n ≥ 0, ∀i∈C, ∀j∈Z.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R002-x-Cn","v141-c-R002-x-Dn","v141-c-R002-x-cij","v141-c-R002-x-dji"],"parameter_refs":["v141-c-R002-p-b","v141-c-R002-p-s","v141-c-R002-p-eta","v141-c-R002-p-rho","v141-c-R002-p-cmin","v141-c-R002-p-cmax","v141-c-R002-p-Dmax"],"evidence_ids":["v141-b-g02-E04","v141-b-g02-E11"]},{"constraint_id":"v141-c-R002-C003","kind":"procedural","role":"core","statement":"The bid-convergence stopping rule terminates the iterative local allocation procedure when both relative bid-price differences fall below ε. Scope: Convergence testing in the unchanged-participant branch of Algorithm 1 for local allocation. Condition: The newest bid prices satisfy both RDB\u003cε and RDS\u003cε.","expression":"RDB \u003c ε ∧ RDS \u003c ε, where RDB = |b_{ij}^{n(t)} − b_{ij}^{n(t−1)}| / b_{ij}^{n(t)} and RDS = |s_{ji}^{n(t)} − s_{ji}^{n(t−1)}| / s_{ji}^{n(t)}.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":[],"parameter_refs":["v141-c-R002-p-b","v141-c-R002-p-s","v141-c-R002-p-epsilon"],"evidence_ids":["v141-b-g02-E18","v141-b-g02-E19"]},{"constraint_id":"v141-c-R002-C004","kind":"procedural","role":"core","statement":"The local allocation and bid-update steps repeat while the bid-price convergence test is not satisfied. Scope: Convergence testing in the unchanged-participant branch of Algorithm 1 for local allocation. Condition: The newest bid prices do not satisfy both RDB\u003cε and RDS\u003cε.","expression":"¬(RDB \u003c ε ∧ RDS \u003c ε), with RDB and RDS defined as in v141-c-R002-C003.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":[],"parameter_refs":["v141-c-R002-p-b","v141-c-R002-p-s","v141-c-R002-p-epsilon"],"evidence_ids":["v141-b-g02-E19"]},{"constraint_id":"v141-c-R002-C005","kind":"procedural","role":"core","statement":"The current local allocation procedure is terminated and a restart of Algorithm 1 is prepared. Scope: Participant-change branch of Algorithm 1 during current localized P2P trading. Condition: The participating PHEVs of the current localized P2P electricity trading change.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E18"]},{"constraint_id":"v141-c-R002-C006","kind":"procedural","role":"core","statement":"Algorithm 1 may be restarted with its parameters reinitialized on demand. Scope: On-demand restart of the localized iterative allocation procedure following an unexpected event. Condition: An unexpected event, such as abrupt disconnection of scheduled PHEVs, activates a trigger.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E20"]},{"constraint_id":"v141-c-R002-C007","kind":"mathematical","role":"supporting","statement":"Relative bid-price differences used by the stopping rule are defined as RDB = |b_{ij}^{n(t)} − b_{ij}^{n(t−1)}| / b_{ij}^{n(t)} and RDS = |s_{ji}^{n(t)} − s_{ji}^{n(t−1)}| / s_{ji}^{n(t)}.","expression":"RDB = |b_{ij}^{n(t)} − b_{ij}^{n(t−1)}| / b_{ij}^{n(t)}, RDS = |s_{ji}^{n(t)} − s_{ji}^{n(t−1)}| / s_{ji}^{n(t)}.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":[],"parameter_refs":["v141-c-R002-p-b","v141-c-R002-p-s"],"evidence_ids":["v141-b-g02-E18"]}],"pi":[{"evidence_id":"v141-b-g02-E04","location":{"location_id":"src-2be1f33ba6-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":"3158","section":"IV. PROBLEM DEFINITION FOR ELECTRICITY TRADING","anchor_text":"j i η ij i , , j=1 w th I an dnji ≤Dn,maxj , ∀j ∈Z, au i=1 ρdnji = cnij, ∀i ∈C, ∀j ∈Z, cnij ≥0, ∀i ∈","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Subject to: c_i^{n,min} ≤ η ∑_{j=1}^{J} c_{ij}^n ≤ c_i^{n,max}, ∀i ∈ C, ∑_{i=1}^{I} d_{ji}^n ≤ D_j^{n,max}, ∀j ∈ Z, ρ d_{ji}^n = c_{ij}^n, ∀i ∈ C, ∀j ∈ Z, c_{ij}^n ≥ 0, ∀i ∈ C, ∀j ∈ Z. (4) Here, ρ is average electricity transmission efficiency of the local electricity trading. The objective function in (3) is strictly concave with compact and convex constraints, so there exists a unique optimal solution using Karush–Kuhn–Tucker (KKT) conditions [16]."},{"evidence_id":"v141-b-g02-E08","location":{"location_id":"src-2be1f33ba6-p06-c1r1__v141-a-M01-bidding","page":6,"printed_page":"3159","section":"V. ITERATIVE DOUBLE AUCTION MECHANISM","anchor_text":"KANG et al.: ENABLING LOCALIZED PEER-TO-PEER ELECTRICITY TRADING AMONG electricity, which is useful ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In this section, an iterative double auction mechanism is proposed to elicit hidden information about PHEVs to energy brokers in order to maximize social welfare. In a hotspot, an energy broker acts as an auctioneer to perform an iterative double auction according to buying prices from charging PHEVs and selling prices from the discharging ones. In this way, the auctioneer determines the final trading prices and the amount of traded electricity, which is useful to avoid directly revealing private information of PHEVs during electricity trading. More specifically, each charging PHEV CV_i submits a bid price b_{ij} ≥ 0 for each discharging PHEV DV_j to the auctioneer. And each discharging PHEV DV_j also submits a bid price s_{ji} ≥ 0 for each charging PHEV CV_i to the auctioneer. After receiving these bid prices, the auctioneer solves an optimal energy allocation problem based on the bids from PHEVs, and thus allocates electricity for every PHEV to achieve effective market equilibrium [17]."},{"evidence_id":"v141-b-g02-E11","location":{"location_id":"src-2be1f33ba6-p06-c1r4__v141-a-M01-clearing","page":6,"printed_page":"3159","section":"V. ITERATIVE DOUBLE AUCTION MECHANISM","anchor_text":"I J A : max [bnij lncnij −snjidnji] (10) Cn ,Dn i=1 j=1 ∂p subject to the same constraints in (4). F","equation_id":"(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"3) Auctioneer: The bid price matrices from charging and discharging PHEVs are submitted to the auctioneer for performing an iterative double auction mechanism with multiple iterations. The buyers and sellers respectively solve their own optimal electricity buying and selling problems at each iteration to update bid price vectors according to the auctioneer’s newly allocated demand and supply, respectively. The auctioneer solves the following optimal allocation problem A to calculate the amount of traded electricity [18]: A: max_{C^n,D^n} ∑_{i=1}^{I}∑_{j=1}^{J} [ b_{ij}^n ln c_{ij}^n − s_{ji}^n d_{ji}^n ] (10) subject to the same constraints in (4). From (10), if the bid prices of charging and discharging PHEVs are given, the auctioneer can solve Problem A. Note that both Problems A and SW have the same constraints. Problem A is also strictly concave, which ensures that there exists a unique optimal solution for A. For (10), we carry out constraint relaxation through Lagrangian L2. To ensure that the optimal solution of Problem A also solves Problem SW, it is necessary that all KKT conditions along with the stationary conditions are matched for both Problem A and Problem SW. Therefore, L2 and L1 have the same Lagrange multipliers."},{"evidence_id":"v141-b-g02-E18","location":{"location_id":"src-2be1f33ba6-p07-c1r2__v141-a-M01-coordination","page":7,"printed_page":"3160","section":"C. Algorithm Implementation","anchor_text":"ji 1 ji 2 ( ) m AEquations (21) and (14) are also the same. It is known that the smpricing rules bas","equation_id":"Algorithm 1","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"// RDB = |b_{ij}^{n(t)} − b_{ij}^{n(t−1)}| / b_{ij}^{n(t)}, RDS = |s_{ji}^{n(t)} − s_{ji}^{n(t−1)}| / s_{ji}^{n(t)}. 1: Input: ε, η, τ, STO^n; 2: Initialization: B^n(0), S^n(0), t←0, flag←1, trigger←0; 3: while flag and ∼trigger do 4: if Participating PHEVs of current localized P2P electricity trading change then 5: trigger←1, and the auctioneer terminates the procedure and prepares to restart Algorithm 1. 6: else 7: Based on B^n(t) and S^n(t), the auctioneer solves Problem A to get C^n(t) and D^n(t), and then broadcasts the optimized results to charging PHEVs and discharging PHEVs, respectively. 8: Based on C^n(t) and D^n(t), charging PHEVs compute their optimal bid prices B^n(t+1) through solving Problem EB, and submit them to the auctioneer; 9: Based on C^n(t) and D^n(t), discharging PHEVs compute their optimal bid prices S^n(t+1) through solving Problem ES, and also submit them to the auctioneer; 10: t←t+1; 11: if RDB\u003cε and RDS\u003cε, then 12: flag←0, t←t−1. 13: end if 14: end if 15: end while 16: Output: C^n(t), D^n(t), B^n(t+1), S^n(t+1)"},{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-2be1f33ba6-p07-c2r1__v141-a-M01-coordination","page":7,"printed_page":"3160","section":"C. Algorithm Implementation","anchor_text":"TRANSACTIONS ON INDUSTRIAL INFORMATICS, VOL. 13, NO. 6, DECEMBER 2017 new allocation solution to the","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"According to the proposed mechanism, the charging PHEVs and the discharging PHEVs submit initial bid price vectors (i.e., B^n and S^n) based on their preferences to the auctioneer in the first iteration. Through these initial bid prices, the auctioneer solves Problem A to allocate the electricity demand and supply based on their individual bids. The auctioneer broadcasts a new allocation solution to the charging and discharging PHEVs. Then these PHEVs solve their own Problem ES and Problem EB in order to obtain optimal bid prices for the next iteration. The auctioneer checks a termination condition of Algorithm 1 based on newly submitted bid prices from the PHEVs. Here, the termination condition is that whether the newest bid prices satisfy the convergence criteria (i.e., RDB\u003cε and RDS\u003cε) or not. If not, the entities in this algorithm repeatedly execute the above steps. Problems EB, ES, and A can be solved through multiple iterations. Here, ε determines the execution time of Algorithm 1 and accuracy of final results. When ε becomes smaller, the final results will get closer to the optimal values but increase time and iterations of the algorithm. Selection of the value of ε is a tradeoff between time and accuracy of the algorithm."},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-2be1f33ba6-p07-c2r2__v141-a-M01-validation","page":7,"printed_page":"3160","section":"C. Algorithm Implementation","anchor_text":") multiple iterations. Here, ε determines the execution time of Algorithm 1 and accuracy of ﬁnal res","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"exception"},"source_text":"In addition, auctioneers monitor localized P2P electricity trading in real time. When some unexpected events happen, e.g., abrupt disconnection of scheduled PHEVs, a trigger will be activated. Then the auctioneers may restart Algorithm 1 and reinitialize parameters on demand. A new electricity trading procedure is executed in time. Besides, similar to that in [6], we consider that few PHEVs suddenly leave from scheduled trades in parking lots during a specified scheduling time period. The abruptly disconnected PHEVs will be held accountable and will be made pay for a penalty of disconnection. This algorithm is performed with acceptable overheads in practice with low frequency of restart."},{"evidence_id":"v141-b-g02-E00","location":{"location_id":"src-2be1f33ba6-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":"3157","section":"IV. PROBLEM DEFINITION FOR ELECTRICITY TRADING","anchor_text":"s, between any charging PHEV and any discharging PHEV in the s- network [14]. A local aggregator LAG","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A set of LAGs (denoted as ι) is indexed by n, where n ∈ ι ≜ {1, 2 . . . n}. Let us denote a set of charging PHEVs in LAGn as υ ≜ (CV_i^n | i ∈ C, n ∈ ι), C = {0, 1, 2, . . . , I}. The discharging PHEVs in LAGn are denoted as ψ ≜ (DV_j^n | j ∈ Z, n ∈ ι), Z = {0, 1, 2, . . . , J}. c_i^{n,min} and c_i^{n,max} are the minimum and maximum of electricity demand for CV_i^n ∈ R in LAGn, respectively. LAGn must provide c_i^{n,min} energy to CV_i^n for normal driving. Here, c_{ij}^n is the electricity demand of CV_i^n for discharging PHEV DV_j^n in LAGn."},{"evidence_id":"v141-b-g02-E01","location":{"location_id":"src-2be1f33ba6-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":"3158","section":"IV. PROBLEM DEFINITION FOR ELECTRICITY TRADING","anchor_text":"3158 IEEE TRANSA Cni Δ= {cnij|j ∈Z}. In LAGn, the total electricity demand of all th charging PHEVs ","equation_id":"(1)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"C_i^n ≜ {c_{ij}^n | j ∈ Z}. In LAGn, the total electricity demand of all charging PHEVs is C^n ≜ {C_i^n | i ∈ C}. We define the energy state of CV_i^n before charging as STO_i^n. EV_i^{cap} is the battery capacity of CV_i^n. The satisfaction function of CV_i^n is U_i(C_i^n)=w_i ln( η ∑_{j=1}^{J} c_{ij}^n − c_i^{n,min}+1 ) (1) where η is average charging efficiency from discharging PHEVs to CV_i^n, w_i = τ / STO_i^n is the charging willingness of CV_i^n, and τ is a constant."},{"evidence_id":"v141-b-g02-E02","location":{"location_id":"src-2be1f33ba6-p05-c1r2__v141-a-M01-clearing","page":5,"printed_page":"3158","section":"IV. PROBLEM DEFINITION FOR ELECTRICITY TRADING","anchor_text":"where η is average charging efﬁciency from discharging PHEVs n is the charging willingness of CV in ","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"For the discharging PHEVs, d_{ji}^n is the amount of electricity supply from discharging PHEV DV_j^n to CV_i^n in LAGn. The electricity supply vector of DV_j^n is D_j^n ≜ {d_{ji}^n | i ∈ R}. In LAGn, the total electricity supply of all discharging PHEVs is D^n ≜ {D_j^n | j ∈ Z}. The maximum of electricity supply for a discharging PHEV in LAGn is D_j^{n,max}. In LAGn, the cost function of DV_j^n is L_j(D_j^n)=l_1 ∑_{i=1}^{I}(d_{ji}^n)^2 + l_2 ∑_{i=1}^{I}d_{ji}^n (2) where l_1 and l_2 are cost factors. Here, l_1 > 0."},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-2be1f33ba6-p08-c1r4__v141-a-M01-clearing","page":8,"printed_page":"3161","section":"B. Numerical Results","anchor_text":"pp y g parking lots (see Fig. 4). We formulate electricity consumption tra behavior of PHEV as recor","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"Therefore, we set the battery capacity of the PHEVs to 24 KWh. The minimum and maximum of electricity demand for charging PHEVs are [5, 10] KWh and [12, 18] KWh, respectively. The maximum of electricity supply for discharging PHEVs is [10, 20] KWh. The cost factors of cost function, i.e., l_1 and l_2 in (2), are set to 0.01 and 0.015, respectively. The average charging efficiency η is 0.8 and the average electricity transmission efficiency ρ is 0.9. The minimum reward for a discharging PHEV r_j^{min} randomly ranges from 1 to 2 dollars. The convergence threshold ε is 0.001. We take a parking lot with 35 charging PHEVs and 45 discharging in LAG1 as an example."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-matching","v141-a-M01-settlement","v141-a-M01-validation"],"extras":{"decision_anchor":"clearing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E08","quote":"In a hotspot, an energy broker acts as an auctioneer to perform an iterative double auction according to buying prices from charging PHEVs and selling prices from the discharging ones."},{"evidence_id":"v141-b-g02-E11","quote":"The auctioneer solves the following optimal allocation problem A to calculate the amount of traded electricity [18]:"}],[{"evidence_id":"v141-b-g02-E11","quote":"A: max_{C^n,D^n} ∑_{i=1}^{I}∑_{j=1}^{J} [ b_{ij}^n ln c_{ij}^n − s_{ji}^n d_{ji}^n ] (10) subject to the same constraints in (4)."},{"evidence_id":"v141-b-g02-E04","quote":"Subject to: c_i^{n,min} ≤ η ∑_{j=1}^{J} c_{ij}^n ≤ c_i^{n,max}, ∀i ∈ C, ∑_{i=1}^{I} d_{ji}^n ≤ D_j^{n,max}, ∀j ∈ Z, ρ d_{ji}^n = c_{ij}^n, ∀i ∈ C, ∀j ∈ Z, c_{ij}^n ≥ 0, ∀i ∈ C, ∀j ∈ Z. (4)"}],[{"evidence_id":"v141-b-g02-E18","quote":"11: if RDB\u003cε and RDS\u003cε, then 12: flag←0, t←t−1."},{"evidence_id":"v141-b-g02-E19","quote":"Here, the termination condition is that whether the newest bid prices satisfy the convergence criteria (i.e., RDB\u003cε and RDS\u003cε) or not."}],[{"evidence_id":"v141-b-g02-E19","quote":"The auctioneer checks a termination condition of Algorithm 1 based on newly submitted bid prices from the PHEVs. Here, the termination condition is that whether the newest bid prices satisfy the convergence criteria (i.e., RDB\u003cε and RDS\u003cε) or not. If not, the entities in this algorithm repeatedly execute the above steps."}],[{"evidence_id":"v141-b-g02-E18","quote":"4: if Participating PHEVs of current localized P2P electricity trading change then 5: trigger←1, and the auctioneer terminates the procedure and prepares to restart Algorithm 1."}],[{"evidence_id":"v141-b-g02-E20","quote":"When some unexpected events happen, e.g., abrupt disconnection of scheduled PHEVs, a trigger will be activated. Then the auctioneers may restart Algorithm 1 and reinitialize parameters on demand."}]],"C2_formalization":{"graph_sha256":"5b30305eec561b05e0507c9cb77b7fce5183f530d65ab3cd4484d70a0254cf57","applicability":"formalized","reason":"The supplied source quotations support a mathematical formulation of Problem A in (10) with constraints in (4) and the bid-convergence condition in Algorithm 1. These are transcribed as source expressions. The participant-change and restart branches remain procedural because the graph does not model participant sets, restart events, or trigger variables. B evidence remains unreviewed in this experiment; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R002-x-Cn","node_ids":["clearing.local"],"edge_ids":[],"rationale":"C^n is the aggregate demand allocation variable over which Problem A maximizes; it is part of the local clearing operation."},{"object_id":"v141-c-R002-x-Dn","node_ids":["clearing.local"],"edge_ids":[],"rationale":"D^n is the aggregate supply allocation variable over which Problem A maximizes; it is part of the local clearing operation."},{"object_id":"v141-c-R002-x-cij","node_ids":["clearing.local"],"edge_ids":[],"rationale":"c_{ij}^n is the bilateral demand allocation component constrained in (4) and entering the Problem A objective (10)."},{"object_id":"v141-c-R002-x-dji","node_ids":["clearing.local"],"edge_ids":[],"rationale":"d_{ji}^n is the bilateral supply allocation component constrained in (4) and entering the Problem A objective (10)."},{"object_id":"v141-c-R002-p-b","node_ids":["clearing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"b_{ij}^n is a bid input used by the auctioneer when solving Problem A; edge E001 links the local operator to clearing."},{"object_id":"v141-c-R002-p-s","node_ids":["clearing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"s_{ji}^n is a bid input used by the auctioneer when solving Problem A; edge E001 links the local operator to clearing."},{"object_id":"v141-c-R002-p-eta","node_ids":["clearing.local"],"edge_ids":[],"rationale":"η appears in the charging-efficiency-adjusted demand bound in (4), a constraint on local clearing."},{"object_id":"v141-c-R002-p-rho","node_ids":["clearing.local"],"edge_ids":[],"rationale":"ρ appears in the transmission-efficiency equality in (4), a constraint on local clearing."},{"object_id":"v141-c-R002-p-cmin","node_ids":["clearing.local"],"edge_ids":[],"rationale":"c_i^{n,min} lower-bounds the charging-efficiency-adjusted demand in (4)."},{"object_id":"v141-c-R002-p-cmax","node_ids":["clearing.local"],"edge_ids":[],"rationale":"c_i^{n,max} upper-bounds the charging-efficiency-adjusted demand in (4)."},{"object_id":"v141-c-R002-p-Dmax","node_ids":["clearing.local"],"edge_ids":[],"rationale":"D_j^{n,max} upper-bounds each discharging PHEV's total supply in (4)."},{"object_id":"v141-c-R002-p-epsilon","node_ids":["clearing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"ε is the convergence threshold checked by the auctioneer in Algorithm 1; edge E001 links the local operator to the clearing procedure."},{"object_id":"v141-c-R002-C002","node_ids":["clearing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"Problem A's objective and constraints formalize the allocation performed at clearing.local; edge E001 identifies the local operator as the auctioneer solving it."},{"object_id":"v141-c-R002-C003","node_ids":["clearing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"The stopping condition is checked by the auctioneer inside the iterative clearing loop; edge E001 links operator and clearing."},{"object_id":"v141-c-R002-C004","node_ids":["clearing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"The continuation condition governs repetition of the auctioneer's local allocation and bid-update loop; edge E001 links operator and clearing."},{"object_id":"v141-c-R002-C007","node_ids":["clearing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"The relative bid-price difference definitions are used by the auctioneer's convergence test in Algorithm 1; edge E001 links operator and clearing."}],"revision_requests":[]}},"quarantined_references":[]}});
